def _normalize_statement_series(series):
    """Normalize yfinance row output into a clean datetime-indexed numeric series."""
    if series is None:
        return None
    if isinstance(series, pd.DataFrame):
        if series.empty:
            return None
        series = series.iloc[0]

    series = pd.to_numeric(series, errors="coerce").dropna()
    if series.empty:
        return None

    index = pd.to_datetime(series.index, errors="coerce")
    normalized = pd.Series(series.values, index=index).dropna()
    normalized = normalized[normalized.index.notna()]
    if normalized.empty:
        return None

    normalized = normalized.groupby(normalized.index).last().sort_index()
    return normalized


def _extract_statement_row(df, aliases):
    """Find a statement row by exact or partial alias match."""
    if df is None or getattr(df, "empty", True):
        return None

    lower_map = {str(idx).strip().lower(): idx for idx in df.index}
    for alias in aliases:
        alias_key = alias.lower()
        if alias_key in lower_map:
            return _normalize_statement_series(df.loc[lower_map[alias_key]])

    for alias in aliases:
        alias_key = alias.lower()
        for idx in df.index:
            idx_key = str(idx).strip().lower()
            if alias_key in idx_key or idx_key in alias_key:
                return _normalize_statement_series(df.loc[idx])

    return None


def _combine_statement_series(quarterly_series, annual_series):
    """Combine annual+quarterly series and prefer quarterly values on overlapping dates."""
    combined = {}
    if annual_series is not None:
        for dt, value in annual_series.items():
            combined[pd.Timestamp(dt)] = float(value)
    if quarterly_series is not None:
        for dt, value in quarterly_series.items():
            combined[pd.Timestamp(dt)] = float(value)

    if not combined:
        return None

    return pd.Series(combined).sort_index()


def _series_to_points(series):
    if series is None or len(series) == 0:
        return []
    points = []
    for dt, value in series.items():
        points.append({"date": pd.Timestamp(dt).strftime("%Y-%m-%d"), "value": float(value)})
    return points


def _safe_float(value):
    try:
        numeric = float(value)
        return numeric if np.isfinite(numeric) else np.nan
    except Exception:
        return np.nan


def _points_to_series(points):
    if not points:
        return None
    parsed = []
    for point in points:
        date_str = point.get("date")
        value = point.get("value")
        if date_str is None or value is None:
            continue
        parsed.append((pd.to_datetime(date_str, errors="coerce"), pd.to_numeric(value, errors="coerce")))

    parsed = [(dt, value) for dt, value in parsed if pd.notna(dt) and pd.notna(value)]
    if not parsed:
        return None

    series = pd.Series({dt: float(value) for dt, value in parsed}).sort_index()
    return series


def build_valuation_history_frame(ticker):
    """Load cached valuation history into a normalized dataframe."""
    valuation_history = cache.load_history(ticker)
    if not valuation_history:
        return pd.DataFrame()

    rows = []
    for date_str, vals in sorted(valuation_history.items()):
        monthly_candle = vals.get("monthly_candle") if isinstance(vals.get("monthly_candle"), dict) else {}
        rows.append(
            {
                "date": pd.to_datetime(date_str, errors="coerce"),
                "price": pd.to_numeric(vals.get("price"), errors="coerce"),
                "fair_value_base": pd.to_numeric(vals.get("fair_value_base"), errors="coerce"),
                "fair_value_low": pd.to_numeric(vals.get("fair_value_low"), errors="coerce"),
                "fair_value_high": pd.to_numeric(vals.get("fair_value_high"), errors="coerce"),
                "candle_open": _safe_float(monthly_candle.get("open")),
                "candle_high": _safe_float(monthly_candle.get("high")),
                "candle_low": _safe_float(monthly_candle.get("low")),
                "candle_close": _safe_float(monthly_candle.get("close")),
                "candle_avg": _safe_float(monthly_candle.get("average")),
                "forward_eps": _safe_float(vals.get("forward_eps")),
                "trailing_eps": _safe_float(vals.get("trailing_eps")),
                "forward_pe": _safe_float(vals.get("forward_pe")),
                "trailing_pe": _safe_float(vals.get("trailing_pe")),
                "peg_display": (
                    f"{vals.get('peg_ratio'):.2f}x"
                    if isinstance(vals.get("peg_ratio"), (int, float))
                    else "n/a"
                ),
                "lynch_signal_label": ((vals.get("lynch_signal") or {}).get("label") or "Unavailable"),
            }
        )

    df = pd.DataFrame(rows)
    if df.empty:
        return df
    df = df.dropna(subset=["date"]).sort_values("date")
    return df


def _series_recent_pct_change(series, min_points=4):
    """Compute a robust recent percent change from a dated numeric series."""
    if series is None:
        return np.nan

    s = pd.to_numeric(series, errors="coerce").dropna()
    if len(s) < min_points:
        return np.nan

    s = s.sort_index()
    window = s.tail(6)
    if len(window) >= 6:
        old_value = float(window.iloc[:3].median())
        new_value = float(window.iloc[-3:].median())
    else:
        old_value = float(window.iloc[0])
        new_value = float(window.iloc[-1])

    if not np.isfinite(old_value) or abs(old_value) < 1e-9:
        return np.nan

    return ((new_value - old_value) / abs(old_value)) * 100.0


def _latest_value(series):
    if series is None:
        return np.nan
    s = pd.to_numeric(series, errors="coerce").dropna()
    if s.empty:
        return np.nan
    return float(s.sort_index().iloc[-1])


def _compute_peg_confirmation(
    revenue_change_pct,
    eps_change_pct,
    fcf_change_pct,
    shares_change_pct,
    operating_income_series,
    revenue_series,
    fcf_series,
    net_income_series,
):
    """
    Score 0–100 fundamental support for the current valuation signal.

    Scoring: positive=+1, neutral=0, negative=−1 per metric; unavailable excluded.
    score = (sum + available_n) / (2 * available_n) * 100
    ≥70 Supported | 40–69 Partly Supported | <40 Weakly Supported
    Requires ≥4 available metrics.
    """
    breakdown = {}

    # --- Growth metrics: positive >+3%, neutral ±3%, negative <−3% ---
    def _classify_growth(value, label):
        if not np.isfinite(value):
            return {"value": None, "status": "unavailable", "label": label}
        if value > 3.0:
            return {"value": round(value, 1), "status": "positive", "label": label}
        if value < -3.0:
            return {"value": round(value, 1), "status": "negative", "label": label}
        return {"value": round(value, 1), "status": "neutral", "label": label}

    breakdown["revenue_growth"] = _classify_growth(revenue_change_pct, "revenue growth")
    breakdown["eps_growth"] = _classify_growth(eps_change_pct, "EPS growth")
    breakdown["fcf_growth"] = _classify_growth(fcf_change_pct, "FCF growth")

    # --- FCF conversion: latest median FCF/NI ratio ---
    # positive ≥80%, neutral 50–80%, negative <50%
    fcf_conv_status = "unavailable"
    fcf_conv_value = None
    if fcf_series is not None and net_income_series is not None:
        common_idx = fcf_series.index.intersection(net_income_series.index)
        if len(common_idx) >= 2:
            ni_c = pd.to_numeric(net_income_series.loc[common_idx], errors="coerce")
            fcf_c = pd.to_numeric(fcf_series.loc[common_idx], errors="coerce")
            valid = ni_c.abs() > 1e-9
            if valid.any():
                ratio_s = (fcf_c[valid] / ni_c[valid]).dropna().sort_index()
                if len(ratio_s) >= 1:
                    latest_ratio = float(ratio_s.tail(3).median())
                    if np.isfinite(latest_ratio):
                        fcf_conv_value = round(latest_ratio * 100.0, 1)
                        if latest_ratio >= 0.80:
                            fcf_conv_status = "positive"
                        elif latest_ratio >= 0.50:
                            fcf_conv_status = "neutral"
                        else:
                            fcf_conv_status = "negative"
    breakdown["fcf_conversion"] = {"value": fcf_conv_value, "status": fcf_conv_status, "label": "cash conversion"}

    # --- Operating margin trend: change in (OpIncome/Revenue) in percentage points ---
    # positive >+0.5pp, neutral ±0.5pp, negative <−0.5pp
    op_margin_status = "unavailable"
    op_margin_value = None
    if operating_income_series is not None and revenue_series is not None:
        common_idx = operating_income_series.index.intersection(revenue_series.index)
        if len(common_idx) >= 4:
            oi_c = pd.to_numeric(operating_income_series.loc[common_idx], errors="coerce")
            rev_c = pd.to_numeric(revenue_series.loc[common_idx], errors="coerce")
            valid = rev_c.abs() > 1e-9
            if valid.any():
                margin_s = (oi_c[valid] / rev_c[valid]).dropna().sort_index() * 100.0
                if len(margin_s) >= 4:
                    w = margin_s.tail(6)
                    if len(w) >= 6:
                        old_m = float(w.iloc[:3].median())
                        new_m = float(w.iloc[-3:].median())
                    else:
                        old_m = float(w.iloc[0])
                        new_m = float(w.iloc[-1])
                    if np.isfinite(old_m) and np.isfinite(new_m):
                        op_margin_value = round(new_m - old_m, 2)
                        if op_margin_value > 0.5:
                            op_margin_status = "positive"
                        elif op_margin_value < -0.5:
                            op_margin_status = "negative"
                        else:
                            op_margin_status = "neutral"
    breakdown["operating_margin_trend"] = {"value": op_margin_value, "status": op_margin_status, "label": "operating margin"}

    # --- Share dilution: positive ≤0%, neutral 0–2%, negative >2% ---
    if np.isfinite(shares_change_pct):
        if shares_change_pct <= 0.0:
            breakdown["share_dilution"] = {"value": round(shares_change_pct, 1), "status": "positive", "label": "share buybacks"}
        elif shares_change_pct > 2.0:
            breakdown["share_dilution"] = {"value": round(shares_change_pct, 1), "status": "negative", "label": "share dilution"}
        else:
            breakdown["share_dilution"] = {"value": round(shares_change_pct, 1), "status": "neutral", "label": "share count"}
    else:
        breakdown["share_dilution"] = {"value": None, "status": "unavailable", "label": "share count"}

    # --- Score ---
    available = [(k, v) for k, v in breakdown.items() if v["status"] != "unavailable"]
    available_n = len(available)

    if available_n < 4:
        return {
            "status": "insufficient",
            "score": None,
            "phrase": "Insufficient confirmation data (fewer than 4 metrics available).",
            "breakdown": breakdown,
        }

    score_sum = sum(1 if v["status"] == "positive" else (-1 if v["status"] == "negative" else 0) for _, v in available)
    raw_score = (score_sum + available_n) / (2 * available_n) * 100
    score = max(0, min(100, round(raw_score)))

    if score >= 70:
        conf_label = "Supported"
    elif score >= 40:
        conf_label = "Partly Supported"
    else:
        conf_label = "Weakly Supported"

    # --- Narrative phrase ---
    positives = [v["label"] for _, v in available if v["status"] == "positive"]
    negatives = [v["label"] for _, v in available if v["status"] == "negative"]

    def _join(items):
        if len(items) == 1:
            return items[0]
        return ", ".join(items[:-1]) + " and " + items[-1]

    if positives and negatives:
        detail = f"{_join(positives).capitalize()} {'are' if len(positives) > 1 else 'is'} supportive; {_join(negatives)} {'reduce' if len(negatives) > 1 else 'reduces'} confidence."
    elif positives:
        detail = f"{_join(positives).capitalize()} {'are' if len(positives) > 1 else 'is'} broadly supportive."
    elif negatives:
        detail = f"{_join(negatives).capitalize()} {'show weakness' if len(negatives) > 1 else 'shows weakness'} over the measured period."
    else:
        detail = "Fundamentals are broadly neutral with no dominant directional signals."

    phrase = f"{conf_label} — {score}/100. {detail}"

    return {
        "status": conf_label,
        "score": score,
        "phrase": phrase,
        "breakdown": breakdown,
    }


def _compute_observed_fundamental_drivers(ticker, fundamentals_payload, history_insight):
    """Classify observed valuation/fundamental patterns with non-causal language."""
    metrics = (fundamentals_payload or {}).get("metrics") or {}
    if not metrics:
        return {
            "status": "limited",
            "message": "Fundamental series are unavailable for pattern classification.",
        }

    def _metric_series(metric_key):
        points = (metrics.get(metric_key) or {}).get("points", [])
        return _points_to_series(points)

    revenue_series = _metric_series("revenue")
    operating_income_series = _metric_series("operating_income")
    net_income_series = _metric_series("net_income")
    fcf_series = _metric_series("free_cash_flow")
    shares_series = _metric_series("shares_outstanding")
    eps_series = _metric_series("eps")

    metric_counts = {
        "revenue": int(0 if revenue_series is None else len(revenue_series.dropna())),
        "operating_income": int(0 if operating_income_series is None else len(operating_income_series.dropna())),
        "net_income": int(0 if net_income_series is None else len(net_income_series.dropna())),
        "free_cash_flow": int(0 if fcf_series is None else len(fcf_series.dropna())),
        "shares_outstanding": int(0 if shares_series is None else len(shares_series.dropna())),
        "eps": int(0 if eps_series is None else len(eps_series.dropna())),
    }

    # Get recent price trend from monthly candles over roughly 18 months.
    price_change_pct = np.nan
    try:
        end_date = pd.Timestamp(datetime.now()).normalize()
        start_date = end_date - pd.Timedelta(days=550)
        price_candles = get_monthly_price_candles(ticker, start_date, end_date)
        if price_candles is not None and not price_candles.empty and "close" in price_candles.columns:
            price_series = pd.Series(
                pd.to_numeric(price_candles["close"], errors="coerce").values,
                index=pd.to_datetime(price_candles["date"], errors="coerce"),
            ).dropna()
            price_change_pct = _series_recent_pct_change(price_series, min_points=4)
    except Exception:
        price_change_pct = np.nan

    eps_change_pct = _series_recent_pct_change(eps_series, min_points=4)
    revenue_change_pct = _series_recent_pct_change(revenue_series, min_points=4)
    operating_income_change_pct = _series_recent_pct_change(operating_income_series, min_points=4)
    net_income_change_pct = _series_recent_pct_change(net_income_series, min_points=4)
    fcf_change_pct = _series_recent_pct_change(fcf_series, min_points=4)
    shares_change_pct = _series_recent_pct_change(shares_series, min_points=4)

    # Cash conversion trend via FCF / Net Income ratio change.
    cash_conversion_delta = np.nan
    if fcf_series is not None and net_income_series is not None:
        common_idx = fcf_series.index.intersection(net_income_series.index)
        if len(common_idx) >= 4:
            ni_common = pd.to_numeric(net_income_series.loc[common_idx], errors="coerce")
            fcf_common = pd.to_numeric(fcf_series.loc[common_idx], errors="coerce")
            valid = ni_common.abs() > 1e-9
            if valid.any():
                ratio = (fcf_common[valid] / ni_common[valid]).dropna().sort_index()
                if len(ratio) >= 4:
                    ratio_window = ratio.tail(6)
                    if len(ratio_window) >= 6:
                        old_ratio = float(ratio_window.iloc[:3].median())
                        new_ratio = float(ratio_window.iloc[-3:].median())
                    else:
                        old_ratio = float(ratio_window.iloc[0])
                        new_ratio = float(ratio_window.iloc[-1])
                    if np.isfinite(old_ratio) and np.isfinite(new_ratio):
                        cash_conversion_delta = new_ratio - old_ratio

    observed_patterns = []

    # Multiple / earnings pattern labels are observational and threshold-based.
    if np.isfinite(price_change_pct) and np.isfinite(eps_change_pct):
        if price_change_pct <= -8.0 and eps_change_pct >= 5.0:
            observed_patterns.append("multiple compression")
        if price_change_pct >= 8.0 and eps_change_pct <= 3.0:
            observed_patterns.append("multiple expansion")
        if price_change_pct >= 8.0 and eps_change_pct >= 8.0:
            observed_patterns.append("earnings-supported appreciation")
        if price_change_pct <= -8.0 and eps_change_pct <= -8.0:
            observed_patterns.append("possible value-trap pattern")

    if np.isfinite(eps_change_pct) and np.isfinite(net_income_change_pct) and np.isfinite(shares_change_pct):
        if eps_change_pct >= 5.0 and abs(net_income_change_pct) <= 5.0 and shares_change_pct <= -2.0:
            observed_patterns.append("buyback-supported EPS growth")

    if np.isfinite(cash_conversion_delta):
        if cash_conversion_delta >= 0.10:
            observed_patterns.append("improving cash conversion")
        elif cash_conversion_delta <= -0.10:
            observed_patterns.append("weakening cash conversion")

    fundamentals_trend = "mixed"
    trend_components = [revenue_change_pct, operating_income_change_pct, fcf_change_pct]
    valid_trends = [x for x in trend_components if np.isfinite(x)]
    if len(valid_trends) >= 2:
        positives = sum(1 for x in valid_trends if x > 3.0)
        negatives = sum(1 for x in valid_trends if x < -3.0)
        if positives >= 2 and negatives == 0:
            fundamentals_trend = "improving"
        elif negatives >= 2 and positives == 0:
            fundamentals_trend = "weakening"

    valuation_state = "fairly priced"
    margin = _safe_float(history_insight.get("current_mispricing"))
    if np.isfinite(margin):
        if margin > 20:
            valuation_state = "significantly undervalued"
        elif margin > 10:
            valuation_state = "undervalued"
        elif margin < -20:
            valuation_state = "significantly overvalued"
        elif margin < -10:
            valuation_state = "overvalued"

    percentile = _safe_float(history_insight.get("current_percentile"))
    historical_median = _safe_float(history_insight.get("historical_median"))
    if np.isfinite(percentile):
        if percentile >= 90:
            history_context = "unusually attractive valuation relative to its observed history"
        elif percentile >= 75:
            history_context = "more attractive than normal relative to history"
        elif percentile <= 10:
            history_context = "unusually expensive relative to its observed history"
        elif percentile <= 25:
            history_context = "more expensive than normal relative to history"
        else:
            history_context = "within its normal historical valuation range"
    else:
        history_context = "historical context is limited"

    # Independent anchors: these are direct valuation cache entries, not interpolated monthly observations.
    independent_anchors = int(history_insight.get("points", 0))
    evidence_counts = list(metric_counts.values())
    evidence_strength = sum(1 for c in evidence_counts if c >= 4)
    # Confidence depends primarily on independent anchors and data quality, not interpolated sample size.
    if independent_anchors >= 8 and evidence_strength >= 4 and len(observed_patterns) >= 2:
        confidence = "high"
    elif independent_anchors >= 4 and evidence_strength >= 3:
        confidence = "moderate"
    else:
        confidence = "low"

    if not observed_patterns:
        if evidence_strength < 2:
            return {
                "status": "limited",
                "message": "Not enough consistent fundamentals history to classify observed patterns yet.",
                "confidence": confidence,
                "metric_counts": metric_counts,
                "independent_anchors": independent_anchors,
            }
        observed_patterns = ["no dominant valuation/fundamental co-movement pattern"]

    # Build four-part narrative with observational language only.
    current_state_text = (
        f"The stock is currently {margin:+.1f}% vs estimated fair value and is classified as {valuation_state}."
        if np.isfinite(margin)
        else "Current valuation state is unavailable due to missing fair-value context."
    )

    historical_context_text = (
        f"This compares with a historical median of {historical_median:+.1f}% "
        f"and places the current valuation at the {percentile:.0f}th percentile, "
        f"indicating an {history_context}."
        if np.isfinite(percentile) and np.isfinite(historical_median)
        else "Historical percentile context is currently unavailable."
    )

    # Join patterns with " and " instead of ", " for cleaner conjunction.
    pattern_summary = " and ".join(observed_patterns[:2])

    peg_confirmation = _compute_peg_confirmation(
        revenue_change_pct=revenue_change_pct,
        eps_change_pct=eps_change_pct,
        fcf_change_pct=fcf_change_pct,
        shares_change_pct=shares_change_pct,
        operating_income_series=operating_income_series,
        revenue_series=revenue_series,
        fcf_series=fcf_series,
        net_income_series=net_income_series,
    )
    confirmation_phrase = peg_confirmation.get("phrase", "")

    fundamental_explanation_text = (
        f"Observed patterns are consistent with {pattern_summary}. "
        f"Revenue, operating income, and free cash flow have also been trending {fundamentals_trend}."
        + (f" Fundamentals confirmation: {confirmation_phrase}" if confirmation_phrase else "")
    )

    # Use "current discount" when undervalued, "current premium" when overvalued.
    valuation_direction = "discount" if np.isfinite(margin) and margin > 0 else "premium"
    # Get the count of historical observations (points may be monthly interpolated or direct anchors).
    observation_count = int(history_insight.get("points", 0))
    
    conclusion_text = (
        f"The current {valuation_direction} appears {('supported' if fundamentals_trend == 'improving' else 'partly supported' if fundamentals_trend == 'mixed' else 'potentially misleading')} "
        f"by the available fundamental data rather than being driven solely by deteriorating earnings. Confidence is {confidence}, based on {observation_count} historical observations, "
        f"with coverage across {evidence_strength} key fundamental series."
    )

    return {
        "status": "ok",
        "patterns": observed_patterns,
        "trend_classification": fundamentals_trend,
        "confidence": confidence,
        "metric_counts": metric_counts,
        "independent_anchors": independent_anchors,
        "evidence_strength": evidence_strength,
        "peg_confirmation": peg_confirmation,
        "current_state_text": current_state_text,
        "historical_context_text": historical_context_text,
        "fundamental_explanation_text": fundamental_explanation_text,
        "conclusion_text": conclusion_text,
    }


@st.cache_data(ttl=3600)
def get_monthly_price_candles(ticker: str, start_date, end_date):
    """Fetch true monthly OHLC candles for a ticker within the requested window."""
    try:
        stock = yf.Ticker(ticker)
        monthly = stock.history(
            start=pd.Timestamp(start_date) - pd.Timedelta(days=35),
            end=pd.Timestamp(end_date) + pd.Timedelta(days=7),
            interval="1mo",
        )
        if monthly is None or monthly.empty:
            return pd.DataFrame()

        monthly = monthly.copy()
        monthly.index = pd.to_datetime(monthly.index, errors="coerce")
        monthly = monthly[monthly.index.notna()]
        if monthly.empty:
            return pd.DataFrame()
        if getattr(monthly.index, "tz", None) is not None:
            monthly.index = monthly.index.tz_localize(None)

        required_cols = ["Open", "High", "Low", "Close"]
        if not all(col in monthly.columns for col in required_cols):
            return pd.DataFrame()

        out = pd.DataFrame(
            {
                "date": monthly.index,
                "open": pd.to_numeric(monthly["Open"], errors="coerce"),
                "high": pd.to_numeric(monthly["High"], errors="coerce"),
                "low": pd.to_numeric(monthly["Low"], errors="coerce"),
                "close": pd.to_numeric(monthly["Close"], errors="coerce"),
            }
        ).dropna(subset=["open", "high", "low", "close"])
        if out.empty:
            return out

        out["avg"] = (out["open"] + out["high"] + out["low"] + out["close"]) / 4.0
        out = out.sort_values("date")
        out = out[(out["date"] >= pd.Timestamp(start_date)) & (out["date"] <= pd.Timestamp(end_date))]
        return out
    except Exception:
        return pd.DataFrame()


def compute_valuation_history_insight(ticker, current_price, current_fair_value, fundamentals_payload=None):
    """Compute current-vs-history valuation context for popover rendering."""
    def _build_insight_from_history(valid_hist):
        if valid_hist.empty:
            return {"status": "unavailable", "message": "No historical valuation points are available yet."}

        valid_hist = valid_hist.copy()
        valid_hist["mispricing_pct"] = ((valid_hist["fair_value_base"] - valid_hist["price"]) / valid_hist["price"]) * 100.0
        valid_hist = valid_hist[valid_hist["mispricing_pct"].notna()]

        if len(valid_hist) < 6:
            return {
                "status": "limited",
                "message": "Not enough history yet. At least 6 valid points are needed for a stable historical comparison.",
                "points": int(len(valid_hist)),
            }

        if pd.notna(current_price) and pd.notna(current_fair_value) and current_price > 0:
            current_mispricing = ((current_fair_value - current_price) / current_price) * 100.0
        else:
            current_mispricing = float(valid_hist["mispricing_pct"].iloc[-1])

        hist_series = valid_hist["mispricing_pct"].astype(float)
        hist_avg = float(hist_series.mean())
        hist_median = float(hist_series.median())
        hist_low = float(hist_series.min())
        hist_high = float(hist_series.max())
        p10 = float(np.percentile(hist_series, 10))
        p90 = float(np.percentile(hist_series, 90))
        current_percentile = float((hist_series <= current_mispricing).mean() * 100.0)
        delta_vs_avg = float(current_mispricing - hist_avg)
        delta_vs_median = float(current_mispricing - hist_median)

        if delta_vs_median >= 10:
            verdict = "more undervalued than its own historical median"
        elif delta_vs_median <= -10:
            verdict = "more expensive than its own historical median"
        else:
            verdict = "close to its own historical valuation median"

        window_days = int((valid_hist["date"].max() - valid_hist["date"].min()).days)
        window_years = max(window_days / 365.25, 0.25)

        summary = (
            f"Over the past {window_years:.1f} years, this stock's historical median was "
            f"{hist_median:+.1f}% vs fair value (average: {hist_avg:+.1f}%). "
            f"Today it is at {current_mispricing:+.1f}%, which is {delta_vs_median:+.1f} pts and {verdict}."
        )

        return {
            "status": "ok",
            "points": int(len(hist_series)),
            "forward_snapshot_points": int(valid_hist["forward_eps"].notna().sum()) if "forward_eps" in valid_hist.columns else 0,
            "latest_forward_eps": _safe_float(valid_hist["forward_eps"].dropna().iloc[-1]) if "forward_eps" in valid_hist.columns and valid_hist["forward_eps"].notna().any() else None,
            "latest_forward_pe": _safe_float(valid_hist["forward_pe"].dropna().iloc[-1]) if "forward_pe" in valid_hist.columns and valid_hist["forward_pe"].notna().any() else None,
            "summary": summary,
            "current_mispricing": current_mispricing,
            "historical_average": hist_avg,
            "historical_median": hist_median,
            "historical_low": hist_low,
            "historical_high": hist_high,
            "p10": p10,
            "p90": p90,
            "current_percentile": current_percentile,
            "delta_vs_average": delta_vs_avg,
            "delta_vs_median": delta_vs_median,
        }

    history_df = build_valuation_history_frame(ticker)
    valid_hist = history_df[
        history_df["price"].notna()
        & history_df["fair_value_base"].notna()
        & (history_df["price"] > 0)
    ].copy()
    if valid_hist.empty:
        return _build_insight_from_history(valid_hist)

    # Dense monthly insight: interpolate fair value between valuation anchors and
    # pair with monthly closes for better statistical stability.
    dense_hist = None
    try:
        if len(valid_hist) >= 2:
            anchor_min = pd.Timestamp(valid_hist["date"].min())
            anchor_max = pd.Timestamp(valid_hist["date"].max())

            candle_df = get_monthly_price_candles(ticker, anchor_min, anchor_max)
            if candle_df.empty:
                candle_df = (
                    history_df[["date", "candle_close"]]
                    .rename(columns={"candle_close": "close"})
                    .dropna(subset=["date", "close"])
                    .sort_values("date")
                )

            monthly_close = pd.Series(dtype=float)
            if not candle_df.empty:
                monthly_close = pd.Series(
                    pd.to_numeric(candle_df["close"], errors="coerce").values,
                    index=pd.to_datetime(candle_df["date"], errors="coerce"),
                ).dropna()
                monthly_close = monthly_close[monthly_close.index.notna()]
                monthly_close = monthly_close[(monthly_close.index >= anchor_min) & (monthly_close.index <= anchor_max)]
                monthly_close = monthly_close.sort_index()

            fair_anchor = (
                valid_hist.dropna(subset=["date", "fair_value_base"])
                .set_index("date")["fair_value_base"]
                .astype(float)
                .sort_index()
            )

            if len(fair_anchor) >= 2 and len(monthly_close) > 0:
                all_idx = fair_anchor.index.union(monthly_close.index).sort_values()
                fair_interp = fair_anchor.reindex(all_idx).interpolate(method="time").ffill().bfill()
                fair_monthly = fair_interp.reindex(monthly_close.index)

                dense_hist = pd.DataFrame(
                    {
                        "date": monthly_close.index,
                        "price": monthly_close.values,
                        "fair_value_base": fair_monthly.values,
                    }
                )
                dense_hist = dense_hist.dropna(subset=["date", "price", "fair_value_base"])
                dense_hist = dense_hist[dense_hist["price"] > 0]
    except Exception:
        dense_hist = None

    if dense_hist is not None and len(dense_hist) >= 6:
        insight = _build_insight_from_history(dense_hist)
    else:
        insight = _build_insight_from_history(valid_hist)

    if insight.get("status") == "ok" and fundamentals_payload is not None:
        insight["fundamental_drivers"] = _compute_observed_fundamental_drivers(
            ticker=ticker,
            fundamentals_payload=fundamentals_payload,
            history_insight=insight,
        )

    return insight


@st.cache_data(ttl=3600)
def get_fundamentals_payload(ticker: str, months_back: int):
    """Fetch and normalize fundamentals for selector-driven overlay chart."""
    payload = {
        "metrics": {},
        "status_messages": [],
    }

    try:
        stock = yf.Ticker(ticker)
        info = stock.info or {}
    except Exception as exc:
        payload["status_messages"].append(f"Could not load fundamentals for {ticker}: {exc}")
        return payload

    try:
        q_fin = stock.quarterly_financials
    except Exception:
        q_fin = None
    try:
        fin = stock.financials
    except Exception:
        fin = None
    try:
        q_cash = stock.quarterly_cashflow
    except Exception:
        q_cash = None
    try:
        cash = stock.cashflow
    except Exception:
        cash = None
    try:
        q_bal = stock.quarterly_balance_sheet
    except Exception:
        q_bal = None
    try:
        bal = stock.balance_sheet
    except Exception:
        bal = None

    cutoff = pd.Timestamp(datetime.now() - timedelta(days=int(months_back * 30)))

    def clip_series(series):
        if series is None:
            return None
        clipped = series[series.index >= cutoff]
        return clipped if len(clipped) > 0 else series

    def build_metric_entry(metric_key, base_series, message=None, status="ok", proxy_value=None):
        style = FUNDAMENTAL_METRIC_STYLES[metric_key]
        series = clip_series(base_series)
        return {
            "label": style["label"],
            "unit": style["unit"],
            "color": style["color"],
            "status": status,
            "message": message,
            "points": _series_to_points(series),
            "proxy_value": proxy_value,
        }

    # Core statement series
    revenue = _combine_statement_series(
        _extract_statement_row(q_fin, ["Total Revenue", "Operating Revenue"]),
        _extract_statement_row(fin, ["Total Revenue", "Operating Revenue"]),
    )
    gross_profit = _combine_statement_series(
        _extract_statement_row(q_fin, ["Gross Profit"]),
        _extract_statement_row(fin, ["Gross Profit"]),
    )
    operating_income = _combine_statement_series(
        _extract_statement_row(q_fin, ["Operating Income", "Ebit"]),
        _extract_statement_row(fin, ["Operating Income", "Ebit"]),
    )
    net_income = _combine_statement_series(
        _extract_statement_row(q_fin, ["Net Income", "Net Earnings"]),
        _extract_statement_row(fin, ["Net Income", "Net Earnings"]),
    )

    ocf = _combine_statement_series(
        _extract_statement_row(q_cash, ["Operating Cash Flow"]),
        _extract_statement_row(cash, ["Operating Cash Flow"]),
    )
    capex = _combine_statement_series(
        _extract_statement_row(q_cash, ["Capital Expenditure"]),
        _extract_statement_row(cash, ["Capital Expenditure"]),
    )
    fcf_row = _combine_statement_series(
        _extract_statement_row(q_cash, ["Free Cash Flow"]),
        _extract_statement_row(cash, ["Free Cash Flow"]),
    )

    shares_series = _combine_statement_series(
        _extract_statement_row(
            q_bal,
            [
                "Ordinary Shares Number",
                "Share Issued",
                "Common Stock Shares Outstanding",
                "Diluted Average Shares",
                "Basic Average Shares",
            ],
        ),
        _extract_statement_row(
            bal,
            [
                "Ordinary Shares Number",
                "Share Issued",
                "Common Stock Shares Outstanding",
                "Diluted Average Shares",
                "Basic Average Shares",
            ],
        ),
    )

    payload["metrics"]["revenue"] = build_metric_entry(
        "revenue",
        revenue,
        status="ok" if revenue is not None else "unavailable",
        message=None if revenue is not None else "Revenue data is unavailable for this ticker.",
    )
    payload["metrics"]["gross_profit"] = build_metric_entry(
        "gross_profit",
        gross_profit,
        status="ok" if gross_profit is not None else "unavailable",
        message=None if gross_profit is not None else "Gross profit is not reported for this ticker.",
    )
    payload["metrics"]["operating_income"] = build_metric_entry(
        "operating_income",
        operating_income,
        status="ok" if operating_income is not None else "unavailable",
        message=None if operating_income is not None else "Operating income is unavailable for this ticker.",
    )
    payload["metrics"]["net_income"] = build_metric_entry(
        "net_income",
        net_income,
        status="ok" if net_income is not None else "unavailable",
        message=None if net_income is not None else "Net income is unavailable for this ticker.",
    )

    fcf_series = None
    fcf_message = None
    if ocf is not None and capex is not None:
        common_dates = ocf.index.intersection(capex.index)
        if len(common_dates) > 0:
            fcf_series = ocf.loc[common_dates] - capex.loc[common_dates].abs()
            fcf_message = "FCF uses Operating Cash Flow - |CapEx| (preferred GAAP proxy)."
    if fcf_series is None:
        fcf_series = fcf_row
        if fcf_series is not None:
            fcf_message = "FCF uses reported Free Cash Flow row (fallback)."

    payload["metrics"]["free_cash_flow"] = build_metric_entry(
        "free_cash_flow",
        fcf_series,
        status="ok" if fcf_series is not None else "unavailable",
        message=fcf_message if fcf_series is not None else "Free cash flow data is unavailable for this ticker.",
    )

    eps_series = None
    eps_status = "unavailable"
    eps_message = "EPS series is unavailable for this ticker."
    # Keep canonical mapping explicit to avoid any trailing/forward inversion.
    trailing_eps = _safe_float(info.get("trailingEps"))
    if pd.isna(trailing_eps):
        trailing_eps = _safe_float(info.get("epsTrailingTwelveMonths"))
    forward_eps = _safe_float(info.get("forwardEps"))
    if pd.isna(forward_eps):
        forward_eps = _safe_float(info.get("epsForward"))
    
    if net_income is not None:
        if shares_series is not None:
            aligned_shares = pd.to_numeric(shares_series.reindex(net_income.index), errors="coerce").ffill().bfill()
            valid = aligned_shares.notna() & (aligned_shares.astype(float) > 0)
            if valid.any():
                eps_series = net_income[valid] / aligned_shares[valid]
                eps_status = "ok"
                eps_message = "EPS estimated from net income and reported shares outstanding."

        if eps_series is None:
            info_shares = _safe_float(info.get("sharesOutstanding"))
            if pd.notna(info_shares) and info_shares > 0:
                eps_series = net_income / float(info_shares)
                eps_status = "estimated"
                eps_message = "EPS estimated using current shares outstanding as a fallback."

    eps_entry = build_metric_entry(
        "eps",
        eps_series,
        status=eps_status,
        message=eps_message,
    )
    # Store current trailing and forward EPS as reference anchors.
    eps_entry["trailing_eps"] = trailing_eps
    eps_entry["forward_eps"] = forward_eps
    payload["metrics"]["eps"] = eps_entry

    shares_status = "ok" if shares_series is not None else "proxy"
    shares_message = None
    proxy_shares = None
    if shares_series is None:
        proxy_shares = _safe_float(info.get("sharesOutstanding"))
        if pd.notna(proxy_shares) and proxy_shares > 0:
            shares_message = "Shares outstanding uses current point-in-time data as a proxy."
        else:
            shares_status = "unavailable"
            shares_message = "Shares outstanding data is unavailable for this ticker."

    payload["metrics"]["shares_outstanding"] = build_metric_entry(
        "shares_outstanding",
        shares_series,
        status=shares_status,
        message=shares_message,
        proxy_value=float(proxy_shares) if pd.notna(proxy_shares) else None,
    )

    # ── Trailing P/E: hybrid series (annual proxy + quarterly TTM) ────────────────
    # Strategy: Use annual EPS proxy for older periods, switch to quarterly TTM when available.
    # This preserves historical context while being transparent about data quality.
    country = str(info.get("country", "") or "").strip()
    is_international = country not in ("", "United States", "US")
    lag_days = 90 if is_international else 45
    annual_lag_days = 120 if is_international else 60  # Annual reports take longer

    # Extract quarterly EPS records
    quarterly_eps_records: list = []  # list of (publication_date, fiscal_date, quarterly_eps)
    annual_eps_records: list = []  # list of (publication_date, fiscal_year, annual_eps)
    earnings_dates_map: dict = {}  # map fiscal date → publication date
    
    try:
        earn_dates = stock.get_earnings_dates(limit=40)
        if earn_dates is not None and not earn_dates.empty:
            for pub_date, row in earn_dates.iterrows():
                fiscal_date_ts = pd.Timestamp(pub_date).normalize()
                earnings_dates_map[fiscal_date_ts] = fiscal_date_ts
    except Exception:
        pass

    # Extract annual diluted EPS from annual income statement
    try:
        annual_stmt = stock.get_income_stmt(freq="yearly")
        if annual_stmt is not None and not annual_stmt.empty:
            if "DilutedEPS" in annual_stmt.index:
                diluted_eps_annual = annual_stmt.loc["DilutedEPS"]
                for fiscal_year_date, eps_val in diluted_eps_annual.items():
                    val = _safe_float(eps_val)
                    if pd.isna(val):
                        continue
                    fiscal_ts = pd.Timestamp(fiscal_year_date)
                    # Annual reports lag ~60 days (US) / 120 days (international) from year-end
                    annual_lag_days = 120 if is_international else 60
                    pub_date = (fiscal_ts + pd.Timedelta(days=annual_lag_days)).normalize()
                    annual_eps_records.append((pub_date, fiscal_ts, val))  # Store full fiscal_ts for forward-fill
    except Exception:
        pass

    # Extract quarterly diluted EPS from quarterly income statement
    try:
        quarterly_stmt = stock.get_income_stmt(freq="quarterly")
        if quarterly_stmt is not None and not quarterly_stmt.empty:
            if "DilutedEPS" in quarterly_stmt.index:
                diluted_eps_q = quarterly_stmt.loc["DilutedEPS"]
                for fiscal_date, eps_val in diluted_eps_q.items():
                    val = _safe_float(eps_val)
                    if pd.isna(val):
                        continue
                    fiscal_ts = pd.Timestamp(fiscal_date)
                    
                    if fiscal_ts in earnings_dates_map:
                        pub_date = earnings_dates_map[fiscal_ts]
                    else:
                        pub_date = (fiscal_ts + pd.Timedelta(days=lag_days)).normalize()
                    
                    quarterly_eps_records.append((pub_date, fiscal_ts, val))
    except Exception:
        pass

    # Build hybrid P/E series: annual EPS (older) + quarterly TTM (recent)
    # Hierarchy: Annual diluted EPS → Quarterly TTM (4+ quarters) → Quarter × 4 (fallback only)
    
    pe_records: list = []  # list of {"date": date_str, "eps": value, "basis": str, "quality": str}
    
    quarterly_eps_records.sort(key=lambda x: x[0])
    annual_eps_records.sort(key=lambda x: x[0])
    
    # Deduplicate quarterly
    seen_q: dict = {}
    for pub_date, fiscal_ts, eps_val in quarterly_eps_records:
        seen_q[pub_date] = (fiscal_ts, eps_val)
    sorted_quarters = sorted(seen_q.items())
    
    # Deduplicate annual
    seen_a: dict = {}
    for pub_date, fiscal_ts, eps_val in annual_eps_records:
        seen_a[pub_date] = (fiscal_ts, eps_val)  # Store full fiscal_ts for forward-fill date
    sorted_annuals = sorted(seen_a.items())
    
    # Phase 1: Populate with annual EPS records (continuous basis for older history)
    # Use fiscal_ts as date for forward-fill (allows current-year data to apply before pub date)
    if sorted_annuals:
        for a_pub_date, (a_fiscal_ts, a_eps) in sorted_annuals:
            pe_records.append({
                "date": a_fiscal_ts.strftime("%Y-%m-%d"),  # Use fiscal date, not publication date
                "eps": a_eps,
                "basis": "annual_report_eps_proxy",
                "quality": "estimated",
            })
    
    # Phase 2: Overlay with quarterly TTM records (once 4+ quarters available)
    # Use fiscal_ts as date for forward-fill (allows current-quarter data to apply before pub date)
    if len(sorted_quarters) >= 4:
        for q_idx in range(3, len(sorted_quarters)):
            q_pub_date = sorted_quarters[q_idx][0]  # Publication date (for reference)
            q_fiscal_ts = sorted_quarters[q_idx][1][0]  # Fiscal date (for forward-fill)
            ttm_eps = sum(v for _, (_, v) in sorted_quarters[q_idx - 3: q_idx + 1])
            pe_records.append({
                "date": q_fiscal_ts.strftime("%Y-%m-%d"),  # Use fiscal date, not publication date
                "eps": ttm_eps,
                "basis": "quarterly_ttm",
                "quality": "exact",
            })
    
    # Phase 3: Fallback to quarter × 4 only if no annual and insufficient quarterly
    if not sorted_annuals and len(sorted_quarters) < 4:
        for q_idx, (q_pub_date, (q_fiscal_ts, q_eps)) in enumerate(sorted_quarters):
            pe_records.append({
                "date": q_pub_date.strftime("%Y-%m-%d"),
                "eps": q_eps * 4,  # Low-confidence annualization (seasonality risk)
                "basis": "quarter_annualized",
                "quality": "low_confidence",
            })
    
    # Sort all records by date for proper forward-fill
    pe_records.sort(key=lambda x: pd.Timestamp(x["date"]))
    
    # Verify latest quarterly TTM against Yahoo (only if TTM is being used)
    flag_ttm_eps_quality = False
    if any(r["basis"] == "quarterly_ttm" for r in pe_records):
        if len(sorted_quarters) >= 4:
            latest_quarterly_eps = sum(v for _, (_, v) in sorted_quarters[-4:])
            yahoo_trailing_eps = _safe_float(info.get("trailingEps"))
            
            if pd.notna(latest_quarterly_eps) and pd.notna(yahoo_trailing_eps) and yahoo_trailing_eps > 0:
                difference = abs(latest_quarterly_eps - yahoo_trailing_eps) / abs(yahoo_trailing_eps)
                if difference > 0.10:
                    flag_ttm_eps_quality = True

    # If quarterly TTM materially disagrees with provider trailing EPS and
    # annual proxy exists, drop quarterly points to avoid basis-switch jumps.
    if flag_ttm_eps_quality and any(r["basis"] == "annual_report_eps_proxy" for r in pe_records):
        pe_records = [r for r in pe_records if r.get("basis") != "quarterly_ttm"]

    payload["historical_ttm_eps"] = {
        "values": pe_records,
        "source": "annual_eps_and_quarterly_ttm",
        "date_basis": "earnings_date_with_lag_fallback",
        "current_price": _safe_float(info.get("currentPrice") or info.get("regularMarketPrice")),
        "forward_eps": _safe_float(info.get("forwardEps")),
        "ttm_eps_quality_flag": flag_ttm_eps_quality,
    }

    pe_status = "available" if pe_records else "unavailable"
    if flag_ttm_eps_quality and any(r["basis"] == "annual_report_eps_proxy" for r in pe_records):
        pe_status = "partial"  # Annual available, quarterly disabled
    elif flag_ttm_eps_quality:
        pe_status = "unavailable"
    
    basis_summary = []
    if any(r["basis"] == "annual_report_eps_proxy" for r in pe_records):
        basis_summary.append("Annual diluted EPS (estimated)")
    if any(r["basis"] == "quarterly_ttm" for r in pe_records):
        basis_summary.append("Quarterly TTM (exact)")
    if any(r["basis"] == "quarter_annualized" for r in pe_records):
        basis_summary.append("Annualized quarter (low confidence)")
    
    pe_msg = (
        f"Trailing P/E: {' → '.join(basis_summary)}. "
        + "Basis labeled in hover tooltips for transparency."
        if basis_summary
        else (
            "Trailing P/E: quarterly TTM disabled due to >10% reconciliation divergence from Yahoo's trailingEps. "
            "Showing annual EPS proxy basis instead."
            if pe_records and flag_ttm_eps_quality
            else "Trailing P/E data unavailable."
        )
    )
    payload["metrics"]["trailing_pe"] = {
        "label": "Trailing P/E",
        "unit": "ratio",
        "color": "rgba(255,140,0,0.85)",
        "status": pe_status,
        "message": pe_msg,
        "points": [],
    }
    # ─────────────────────────────────────────────────────────────────────────

    return payload
